tool_input.command:
cd "$HOME/.dsh"; echo "=== ALL plugin roots (have cordis.patch.yml) ==="; find . -maxdepth 3 -name cordis.patch.yml 2>/dev/null | sed 's#/cordis.patch.yml##' | sort; echo; echo "=== plugin name/desc/version ==="; node -e '
const fs=require("fs"),path=require("path");
const base=process.env.HOME+"/.dsh";
const dirs=fs.readdirSync(base).filter(d=>{try{return fs.existsSync(path.join(base,d,"package.json"))}catch(e){return false}});
for(const d of dirs){try{const p=JSON.parse(fs.readFileSync(path.join(base,d,"package.json"),"utf8"));console.log(`${d} | ${p.name||""} | ${p.version||""} | ${(p.description||"").slice(0,90)}`)}catch(e){}}
'
